// LC 560：统计连续子数组中和恰好等于 k 的个数
// 换题：改成是否存在时，getOrDefault 得到正数就返回 true；和可能超出 int 时保持 long
public static int subarraySum(int[] nums, int k) {
    Map<Long, Integer> cnt = new HashMap<>();
    cnt.put(0L, 1); // 空前缀，覆盖从下标 0 开始的子数组
    long pre = 0;
    int ans = 0;
    for (int x : nums) {
        pre += x;
        ans += cnt.getOrDefault(pre - k, 0); // 先查再写入，k 为 0 时不会把当前前缀算进自己
        cnt.merge(pre, 1, Integer::sum);
    }
    return ans;
}

// LC 862：数组可含负数，求和至少为 k 的最短连续子数组长度，不存在返回 -1
// 换题：元素都非负时改滑窗。若改成和小于 k 并输出那些数，下面两处 while 是按最短长度设计的，比较方向和答案都要重写
public static int shortestSubarray(int[] nums, int k) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    Deque<Integer> dq = new ArrayDeque<>(); // 存前缀下标，对应的 pre 保持递增
    int ans = n + 1;
    for (int i = 0; i <= n; i++) {
        while (!dq.isEmpty() && pre[i] - pre[dq.peekFirst()] >= k) {
            ans = Math.min(ans, i - dq.pollFirst()); // 这个左端点以后只会形成更长的区间
        }
        while (!dq.isEmpty() && pre[dq.peekLast()] >= pre[i]) dq.pollLast();
        dq.addLast(i);
    }
    return ans <= n ? ans : -1;
}

// LC 1109：bookings 每项为 [first, last, seats]，航班编号 1 到 n
// 在 first 加上座位数，在 last+1 减去，再前缀扫描得到每个航班的总座位
// 换题：0-based 闭区间 [l, r] 加 v 时，对长度 n 的 diff 执行 diff[l]+=v，且只在 r+1<n 时 diff[r+1]-=v；增量很大就把 diff 改成 long[]
public static int[] corpFlightBookings(int[][] bookings, int n) {
    int[] diff = new int[n + 2];
    for (int[] b : bookings) {
        diff[b[0]] += b[2];
        diff[b[1] + 1] -= b[2];
    }
    int[] ans = new int[n];
    for (int i = 1; i <= n; i++) {
        diff[i] += diff[i - 1];
        ans[i - 1] = diff[i];
    }
    return ans;
}

// LC 238：answer[i] 等于除 nums[i] 以外全部元素的乘积，不能用除法
// 先把左侧乘积写入 ans，再从右往左乘后缀积；数组里的 0 不需要单独分支
// 换题：改成除自身以外的和时，乘法换成加法，ans[0] 和 suf 的初值换成 0
public static int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] ans = new int[n];
    ans[0] = 1;
    for (int i = 1; i < n; i++) ans[i] = ans[i - 1] * nums[i - 1];
    int suf = 1;
    for (int i = n - 1; i >= 0; i--) {
        ans[i] *= suf;
        suf *= nums[i];
    }
    return ans;
}

// LC 415：从低位向高位逐位相加，个位先进入 StringBuilder，返回前反转。
// 换题：减法把 carry 改成借位，当前差 < 0 时加 10 并向高位借 1；基数不是 10 时替换下面的 10。
static String addStrings(String num1, String num2) {
    int i = num1.length() - 1;
    int j = num2.length() - 1;
    int carry = 0;
    StringBuilder sb = new StringBuilder();
    while (i >= 0 || j >= 0 || carry > 0) {
        int d1 = 0;
        int d2 = 0;
        if (i >= 0) {
            d1 = num1.charAt(i) - '0';
            i--;
        }
        if (j >= 0) {
            d2 = num2.charAt(j) - '0';
            j--;
        }
        int sum = d1 + d2 + carry;
        sb.append((char) ('0' + sum % 10));
        carry = sum / 10;
    }
    return sb.reverse().toString();
}

// LC 43：num1[i] * num2[j] 累加到 acc[i + j + 1]，再从低位向高位一次进位。
// 无前导零时只有全 0 需要特判；若存在前导零，先剥掉再判断是否为 0。
// 换题：大数除法改为从高位试商，余数 * 基数后加下一位。
static String multiply(String num1, String num2) {
    if (num1.equals("0") || num2.equals("0")) {
        return "0";
    }
    int m = num1.length();
    int n = num2.length();
    int[] acc = new int[m + n];
    for (int i = m - 1; i >= 0; i--) {
        int d1 = num1.charAt(i) - '0';
        for (int j = n - 1; j >= 0; j--) {
            acc[i + j + 1] += d1 * (num2.charAt(j) - '0');
        }
    }
    for (int k = m + n - 1; k > 0; k--) {
        acc[k - 1] += acc[k] / 10;
        acc[k] %= 10;
    }
    StringBuilder sb = new StringBuilder();
    int start = acc[0] == 0 ? 1 : 0;
    for (int k = start; k < acc.length; k++) {
        sb.append((char) ('0' + acc[k]));
    }
    return sb.toString();
}

// LC 54。top/bottom/left/right 是还没输出的边界，每走完一条边立刻收缩。
// 单行或单列时，收缩后必须再用 top<=bottom、left<=right 判断，否则回程会重复或越界。
// 换题：逆时针仍从左上角出发时，依次沿左列向下、下行向右、右列向上、上行向左；
// 每走完一边收缩边界，检查 top<=bottom 且 left<=right 后再走下一边。
// 对角线遍历不要复用这四条边，改按 d=row+col 分组。
static List<Integer> spiralOrder(int[][] matrix) {
    List<Integer> ans = new ArrayList<>();
    if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
        return ans;
    }
    int top = 0;
    int bottom = matrix.length - 1;
    int left = 0;
    int right = matrix[0].length - 1;
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) {
            ans.add(matrix[top][c]);
        }
        top++;
        for (int r = top; r <= bottom; r++) {
            ans.add(matrix[r][right]);
        }
        right--;
        if (top <= bottom) {
            for (int c = right; c >= left; c--) {
                ans.add(matrix[bottom][c]);
            }
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; r--) {
                ans.add(matrix[r][left]);
            }
            left++;
        }
    }
    return ans;
}

// 反转闭区间 [l, r]。l>=r 时直接返回，空区间不会越界。
static void reverseRange(int[] a, int l, int r) {
    while (l < r) {
        int t = a[l];
        a[l] = a[r];
        a[r] = t;
        l++;
        r--;
    }
}

// LC 189 右旋 k：整体反转，再反转前 k 个，再反转剩余部分。
// k 先规范到 [0, n)。Java 中负 k 取模仍为负，使用 Math.floorMod(k, n) 避免先加 n 溢出；负 k 保留为反向轮转。左旋步数先取模再换算，避免直接对 MIN_VALUE 取负。
// 换题：LC 48 先按主对角线转置，再对每一行调用 reverseRange(row, 0, n-1)，得到顺时针 90°。
static void rotate(int[] nums, int k) {
    int n = nums.length;
    if (n == 0) {
        return;
    }
    k = Math.floorMod(k, n);
    reverseRange(nums, 0, n - 1);
    reverseRange(nums, 0, k - 1);
    reverseRange(nums, k, n - 1);
}

