import java.util.*;

class Solution {
    public int mySqrt(int x) {
        int left = 0;
        int right = x;
        int answer = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            long square = (long) mid * mid; // 用 long 避免 mid * mid 溢出。

            if (square <= x) {
                answer = mid;      // 当前 mid 可行，先记下。
                left = mid + 1;    // 继续找更大的可行值。
            } else {
                right = mid - 1;
            }
        }

        return answer;
    }
}

